cpp1m3.inicial:
#include <iostream>
using namespace std;

int main() {
    // 1. Total de moedas (pronto)
    cout << "Total de moedas: " << 3 * 32 + 4 << endl;
    // 2. Cada jogador recebe: o total entre parênteses, dividido por 8
    // 3. Sobram: o resto da mesma divisão (%)
    // 4. Média exata: a divisão por 8.0
    return 0;
}

cpp1m3.solucao:
#include <iostream>
using namespace std;

int main() {
    cout << "Total de moedas: " << 3 * 32 + 4 << endl;
    cout << "Cada jogador recebe: " << (3 * 32 + 4) / 8 << endl;
    cout << "Sobram: " << (3 * 32 + 4) % 8 << endl;
    cout << "Média exata: " << (3 * 32 + 4) / 8.0 << endl;
    return 0;
}

