cpp1m5.inicial:
#include <iostream>
using namespace std;

int main() {
    // 1. Título (pronto)
    cout << "===== LOJA DE JOGOS =====" << endl;
    // 2. Cavaleiros de Pixel: 2 * 60
    // 3. Corrida Estelar: 45
    // 4. Total (2 * 60 + 45) e Pago (200), um em cada linha
    // 5. Troco: 200 - (2 * 60 + 45)
    // 6. Linha em branco
    // 7. Parcela: o total dividido por 4.0
    // 8. Notas de 10 (/ 10) e moedas de 1 (% 10) do troco
    return 0;
}

cpp1m5.solucao:
#include <iostream>
using namespace std;

int main() {
    cout << "===== LOJA DE JOGOS =====" << endl;
    cout << "2x Cavaleiros de Pixel: R$ " << 2 * 60 << endl;
    cout << "1x Corrida Estelar: R$ " << 45 << endl;
    cout << "Total: R$ " << 2 * 60 + 45 << endl;
    cout << "Pago: R$ " << 200 << endl;
    cout << "Troco: R$ " << 200 - (2 * 60 + 45) << endl;
    cout << endl;
    cout << "Em 4x sem juros: R$ " << (2 * 60 + 45) / 4.0 << " por parcela" << endl;
    cout << "Notas de 10 no troco: " << (200 - (2 * 60 + 45)) / 10 << endl;
    cout << "Moedas de 1 no troco: " << (200 - (2 * 60 + 45)) % 10 << endl;
    return 0;
}

